def _open_target_root(target_root: str) -> int:
    """Open the declared target root without following any symlinked component.

    ``O_NOFOLLOW`` on the final name alone says nothing about how the target
    is reached: a root behind a symlinked ancestor is a directory the caller
    did not declare, and ``os.makedirs`` would happily create the missing tail
    through one. Every component is therefore opened the same way, from the
    filesystem root down, and the first symlink (or unopenable component)
    refuses the whole request before any directory is created.
    """
    try:
        fd = os.open(os.path.sep, _DIR_FLAGS)
    except OSError as exc:
        if exc.errno in (errno.ELOOP, errno.EMLINK):
            raise ValueError(f"target_root is a symlink: {target_root!r}") from exc
        raise ValueError(
            f"target_root is not an openable directory: {target_root!r}"
        ) from exc
    parts = [part for part in os.path.abspath(target_root).split(os.path.sep) if part]
    try:
        for part in parts:
            with contextlib.suppress(FileExistsError):
                os.mkdir(part, 0o755, dir_fd=fd)
            child = os.open(part, _DIR_FLAGS, dir_fd=fd)
            os.close(fd)
            fd = child
    except OSError as exc:
        os.close(fd)
        if exc.errno in (errno.ELOOP, errno.EMLINK):
            raise ValueError(
                f"target_root is reached through a symlink: {target_root!r}"
            ) from exc
        raise ValueError(
            f"target_root is not an openable directory: {target_root!r}"
        ) from exc
    return fd


